CREATE TABLE "keyword_rank_tracks" ("id" TEXT NOT NULL, "organization_id" TEXT NOT NULL, "project_id" TEXT, "keyword_id" TEXT NOT NULL, "catalog_product_id" TEXT NOT NULL, "marketplace_id" TEXT NOT NULL, "cadence_minutes" INTEGER NOT NULL, "next_run_at" TIMESTAMP(3), "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, CONSTRAINT "keyword_rank_tracks_pkey" PRIMARY KEY ("id"));
CREATE TABLE "keyword_rank_observations" ("id" TEXT NOT NULL, "organization_id" TEXT NOT NULL, "track_id" TEXT NOT NULL, "provider_key" TEXT NOT NULL, "observed_at" TIMESTAMP(3) NOT NULL, "organic_rank" INTEGER, "sponsored_rank" INTEGER, "freshness_state" "ExternalFreshnessState" NOT NULL, "request_key" TEXT NOT NULL, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "keyword_rank_observations_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "keyword_rank_tracks_unique" ON "keyword_rank_tracks"("organization_id","marketplace_id","keyword_id","catalog_product_id"); CREATE INDEX "keyword_rank_tracks_due" ON "keyword_rank_tracks"("organization_id","next_run_at"); CREATE UNIQUE INDEX "keyword_rank_observations_idempotency" ON "keyword_rank_observations"("track_id","request_key"); CREATE INDEX "keyword_rank_observations_history" ON "keyword_rank_observations"("organization_id","track_id","observed_at");
ALTER TABLE "keyword_rank_tracks" ADD CONSTRAINT "keyword_rank_tracks_org" FOREIGN KEY ("organization_id") REFERENCES "organizations"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "keyword_rank_tracks" ADD CONSTRAINT "keyword_rank_tracks_keyword" FOREIGN KEY ("keyword_id","organization_id") REFERENCES "keywords"("id","organization_id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "keyword_rank_tracks" ADD CONSTRAINT "keyword_rank_tracks_product" FOREIGN KEY ("catalog_product_id") REFERENCES "catalog_products"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "keyword_rank_observations" ADD CONSTRAINT "keyword_rank_observations_org" FOREIGN KEY ("organization_id") REFERENCES "organizations"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "keyword_rank_observations" ADD CONSTRAINT "keyword_rank_observations_track" FOREIGN KEY ("track_id") REFERENCES "keyword_rank_tracks"("id") ON DELETE CASCADE ON UPDATE CASCADE;
